$('#street').addEventListener('pointerdown',()=>{roadWalking=false;clearTimeout(roadTimer);$('#walkRoad').textContent='▶ Walk this road';},{passive:true});
$$('#neighborhoodMovie,#boundaries,#dim').forEach(b=>b.disabled=true);controls();

// Clean Nearby composition: one category, stable numbers, one expanded item.
function placesInCategory(kind){return selectPlacesInCategory(nearby.places,kind)}
function groupCamera(places){return calculateGroupCamera(cameraContext(),places)}
function featureCamera(p){return calculateFeatureCamera(cameraContext(),p)}
function roadCamera(p){return calculateRoadCamera(cameraContext(),p)}
function applyScene(scene){
  selectedPlace=nearby.places.find(p=>p.id===scene.id)||nearby.places[0];
  groupOverview=Boolean(scene.overview);
  renderOverlays();
}
function updateViewContext(){
  const el=$('#viewContext');if(!el)return;
  el.hidden=selectedPlace.id==='home';
  const count=placesInCategory(selectedPlace.kind).length;
  el.textContent=groupOverview?categoryName(selectedPlace.kind)+' · '+count+' places around Waterford':selectedPlace.name+' · with Waterford';
  $('#showGroup').setAttribute('aria-pressed',String(groupOverview));
  if(selectedPlace.id!=='home'){
    $('#featureLegend').textContent=selectedPlace.kind==='road'?'Amber · road alignment, not measured width':selectedPlace.kind==='metro'?'Purple · mapped tracks; arc is not a walking route':selectedPlace.kind==='lake'?'Blue · mapped extent, not current water level':'Arc · straight-line relationship, not a travel route';
    $('#placeName').hidden=groupOverview;
    $('#placeDistance').textContent=groupOverview?'Numbered places · distances are straight-line':distanceLabel(selectedPlace)+' from Waterford · straight-line';
    $('#placeNote').textContent=groupOverview?'Choose a numbered place to focus, or take the category tour.':selectedPlace.note;
    $('#pair').hidden=groupOverview;$('#visitStreet').hidden=groupOverview;$('#placeSource').hidden=groupOverview;$('#descendRoad').hidden=groupOverview||selectedPlace.kind!=='road';
  }
}
$('#descendRoad').onclick=async()=>{
  if(!ready)return;
  const p=selectedPlace;groupOverview=false;
  const established=await moveTo(featureCamera(p),2200);
  if(!established)return;
  updateViewContext();
  $('#viewContext').textContent=p.name+' · descending to the mapped road';
  const completed=await moveTo(roadCamera(p),5200);
  if(completed){updateViewContext();toast('Aerial road view. The highlight is not a width measurement.');}
};
function renderPlaceList(kind){$('#descendRoad').hidden=kind!=='road';const list=placesInCategory(kind);$('#groupCount').textContent=list.length+' '+(list.length===1?'place':'places');$('#showGroup').disabled=list.length<2;$('#tourCategory').textContent='▶ Tour '+categoryName(kind).toLowerCase();const el=$('#placeChoices');el.replaceChildren();list.forEach((p,i)=>{const b=document.createElement('button');b.className=!groupOverview&&p.id===selectedPlace.id?'active':'';b.setAttribute('aria-pressed',String(!groupOverview&&p.id===selectedPlace.id));const n=document.createElement('span');n.className='placeNumber';n.textContent=String(i+1).padStart(2,'0');const title=document.createElement('span');title.className='placeRowName';title.textContent=p.name;const d=document.createElement('small');d.textContent=distanceLabel(p);b.append(n,title,d);b.onclick=()=>choosePlace(p.id);el.append(b)});updateViewContext()}
function renderContextGeometry(){const kind=selectedPlace.kind;const color=kindColor(kind);let segments=[];if(kind==='road')segments=groupOverview?placesInCategory('road').flatMap(p=>p.segments||[]):selectedPlace.segments||[];else if(kind==='metro')segments=nearby.metroSegments||[];else if(selectedPlace.id==='home')return;
 const unique=new Map(segments.map(s=>[s.id,s]));for(const segment of unique.values()){let path=[];const flush=()=>{if(path.length>1){const l=new lib3d.Polyline3DElement({altitudeMode:'CLAMP_TO_GROUND',strokeColor:color,strokeWidth:5,drawsOccludedSegments:false});l.path=path;addOverlay(l)}path=[]};for(const p of segment.path){if(geoDistance(HOME,p)<3200)path.push(p);else flush()}flush()}
}
$('#showGroup').onclick=()=>{if(!ready)return;stop();groupOverview=true;renderOverlays();moveTo(groupCamera(placesInCategory(selectedPlace.kind)),2600)};
$('#tourCategory').onclick=()=>{filmPlayback=null;filmCategory=selectedPlace.kind;neighborhoodFilm()};
function categoryMovieScenes(kind){return buildCategoryScenes({...sceneContext(),kind})}
function movieScenes(){return buildNeighborhoodScenes({...sceneContext(),originalScenes:originalMovieScenes()})}
init();
